SELECT T1.[CardCode] AS 'Customer/Vendor Code', T1.[CardName] AS 'Customer/Vendor Name', T0.[DocEntry] AS 'Document Internal ID', T1.[DocDueDate] AS 'Due Date', T1.[DocCur] AS 'Document Currency', T1.[DocDate] AS 'Posting Date', T1.[DocTime] AS 'Generation Time', T0.[ItemCode] AS 'Item No.', T0.[Quantity] AS 'Quantity', T0.[unitMsr] AS 'Unit', T0.[unitMsr2] AS 'Pur/Sal UoM if BaseUnit', T0.[VatSum] AS 'Total Tax', T0.[VatPrcnt] AS 'Tax Rate per Row', T0.[LineTotal] AS 'Row Total', T0.[WhsCode] AS 'Warehouse Code', T1.[DocTotal] AS 'Document Total', T1.[DocStatus] AS 'Document Status', T1.[CANCELED] AS 'Canceled', T1.[CancelDate] AS 'Cancelation Date' FROM  [dbo].[DLN1] T0  INNER  JOIN [dbo].[ODLN] T1  ON  T1.[DocEntry] = T0.[DocEntry]